extern "C" char *strcpy(char *, const char *);

class stringx
{
    char *chars;
    void *my_buf;
public:
    const char *data() const { return chars; }
};

struct HighScoreData
{
    char initials[4];
    char character[32];
    int score;
    int icons;
};

typedef struct SurferDataStruct
{
    int start_stand;
    int start_turn;
    int start_carve;
    int start_anims;
    int end_anims;
    int trickBook[70];
    int learnedtrickBook[16];
    char name[32];
    char name_ps[32];
    char stashfile[16];
    char firstname[32];
    char lastname[32];
    char fullname[32];
    char abbr[4];
    int goofy;
    int load_in_fe;
    int bio_length;
    int has_movie;
    int attr_spin;
    int attr_speed;
    int attr_balance;
    int attr_air;
    char board_ent_name[20];
    char p_board_name[20];
    int selectable;
    int competitor;
    int initially_unlocked;
    char surfer_nick[20];
    int sort_order;
} SurferData;

extern SurferData SurferDataArray[];

class game
{
    char padding[552];
    int beach_id;
public:
    int get_beach_id() { return beach_id; }
};

extern game *g_game_ptr;

class GlobalDataClass
{
public:
    HighScoreData getBeachHighScore(int beach, int whichScore, bool icons);
    void setBeachHighScore(int beach, int whichScore, bool icons, HighScoreData newScore);
};

extern GlobalDataClass globalCareerData;

class HighScoreFrontEnd
{
public:
    enum { NUM_ROWS = 10 };
};

class FEManager
{
public:
    int AddHighScore(stringx name, int score, int icons, int character);
};

int FEManager::AddHighScore(stringx name, int score, int icons, int character)
{
	// if icons is -1, this means that we aren't looking at the icon challenge high list
	bool icon_mode = icons != -1;
	int beach;
	beach = g_game_ptr->get_beach_id();
	int line = -1;


	HighScoreData temp;
	for(int i=HighScoreFrontEnd::NUM_ROWS-1; i>=0; i--)
	{
		int sc = globalCareerData.getBeachHighScore(beach,i, icon_mode).score;
		int ic = globalCareerData.getBeachHighScore(beach,i, icon_mode).icons;

		if((!icon_mode && score > sc) || (icon_mode && (icons > ic || icons == ic && score > sc)))
		{
			if(i == HighScoreFrontEnd::NUM_ROWS-1)
			{
				temp.initials[0] = name.data()[0];
				temp.initials[1] = name.data()[1];
				temp.initials[2] = name.data()[2];
				temp.initials[3] = '\0';
				strcpy( temp.character, SurferDataArray[character].fullname );
				temp.score = score;
				temp.icons = icons;
				globalCareerData.setBeachHighScore(beach, HighScoreFrontEnd::NUM_ROWS-1, icon_mode, temp);
			}
			else
			{
				HighScoreData hsd = globalCareerData.getBeachHighScore(beach, i, icon_mode);
				globalCareerData.setBeachHighScore(beach, i, icon_mode, globalCareerData.getBeachHighScore(beach,i+1, icon_mode));
				globalCareerData.setBeachHighScore(beach, i+1, icon_mode, hsd);
			}
			line = i;
		}
	}
	return line;
}
